// Gate 4: images. Every <img> in the build is local, has alt, width and height, fits the byte budget,
// and is either generated by the site (og/, favicon) or registered with a license in data/images.json.
import fs from 'node:fs'; import path from 'node:path';
import { ROOT, read, walk, Report } from './lib.mjs';
const r = new Report('images');
const manifest = JSON.parse(read('data/images.json'));
const known = new Set(manifest.map((m) => m.file));
const BANNED = /(CC BY-SA|CC BY-NC|CC BY-ND|NC|ND|all rights reserved)/i;
for (const m of manifest) {
  for (const k of ['image_id', 'file', 'source_url', 'author', 'license', 'license_url', 'accessed', 'alt', 'no_people_or_marks_confirmed']) if (!m[k]) r.err(`images.json ${m.image_id || '?'}: missing ${k}`);
  if (BANNED.test(m.license || '')) r.err(`images.json ${m.image_id}: license ${m.license} not allowed`);
  if (!fs.existsSync(path.join(ROOT, 'public', m.file))) r.err(`images.json ${m.image_id}: file ${m.file} not found`);
}
const PER_IMG = 250 * 1024, PER_PAGE = 900 * 1024;
for (const f of walk('public', '')) {
  const rel = f.replace(/^public\//, '');
  if (/\.(jpe?g|png|webp|avif|gif)$/i.test(rel) && !rel.startsWith('og/') && !known.has(rel)) r.err(`public/${rel}: image not registered in data/images.json`);
}
for (const f of walk('dist', '.html')) {
  const html = read(f); let total = 0;
  for (const m of html.matchAll(/<img\b[^>]*>/g)) {
    const tag = m[0]; const src = (tag.match(/\bsrc="([^"]+)"/) || [])[1] || '';
    if (!/\balt="/.test(tag)) r.err(`${f}: <img ${src}> has no alt attribute`);
    if (!/\bwidth="\d+"/.test(tag) || !/\bheight="\d+"/.test(tag)) r.err(`${f}: <img ${src}> lacks width/height`);
    if (/^https?:\/\//.test(src)) { r.err(`${f}: hotlinked image ${src}`); continue; }
    const p = path.join(ROOT, 'dist', src.split('?')[0]);
    if (!fs.existsSync(p)) { r.err(`${f}: missing image ${src}`); continue; }
    const sz = fs.statSync(p).size; total += sz;
    if (sz > PER_IMG) r.err(`${src}: ${Math.round(sz / 1024)} KB exceeds ${PER_IMG / 1024} KB budget`);
  }
  if (total > PER_PAGE) r.err(`${f}: images total ${Math.round(total / 1024)} KB exceeds page budget`);
}
for (const f of walk('dist/og', '.png')) { const sz = fs.statSync(path.join(ROOT, f)).size; if (sz > PER_IMG) r.err(`${f}: OG image ${Math.round(sz / 1024)} KB over budget`); }
r.done();
